Ext._define('rh.pvf.shiftmanager.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.pvf.shiftmanager.Window',

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {
                        id: 'icons',
                        dataIndex: 'icons',
                        header: '',
                        width: 100,
                        sortable: false,
                        renderer: toolkit.util.formatStatus,
                        menuDisabled: true
                    },
                    {header: 'Descricao', dataIndex: 'unicode', id: 'autoExpandColumn',hidden: true},
                    {header: 'Tipo', dataIndex: 'type_shift_display', width: 120},
                    {header: 'Plantonista', dataIndex: 'employee_unicode', width: 300},
                    {header: 'Lotação', dataIndex: 'workplace_unicode', width: 300},
                    {header: 'Total de dias', dataIndex: 'days', width: 90},
                    {header: 'Data Início', dataIndex: 'start_date', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Data Fim', dataIndex: 'end_date', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y')}
                ]
            );

        return this._columnModel;
    },

    createItem: function(values) {
        if(!this.allowCreate)
            return;

        if(values instanceof Ext.Button)
            values = {};

        values = core.nullValue(values, {});

        if(this.safeMode && !this.getStore().__state.isSearched) {
            Ext.Msg.show({
                title: 'Criação de item bloqueada',
                msg: 'Realize primeiro uma busca do que deseja criar, se não encontrar será liberada a inclusão.',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                scope: this,
                fn: function() {
                    this.getKeywordField().focus();
                }
            });

            this.getKeywordField().markInvalid('Primeiro realize busca aqui.');
        }
        else if(this.getParams().permissions.length == 0){
            Ext.Msg.show({
                title: 'Criação de item bloqueada',
                msg: 'Permissão não encontrada. A permissão de incluir plantão é concedido ao responsável da lotação. Favor, entrar em contato com DGP solicitando a revisão do cadastro da lotação.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                scope: this,
                fn: function() {
                    this.getKeywordField().focus();
                }
            });
        }
        else
            this.factoryRestfulWindow({
                resource: this.resource,
                action: 'create',
                params: this.getParams(),
                values: values,
                ownerGrid: this,
                callback: {
                    success: {
                        scope: this,
                        fn: function(instance) {
                            if(this.driver === 'restful') this.getStore().reload();
                            this.fireEvent('createdItemGrid', instance);
                        }
                    },
                    failure: {
                        scope: this,
                        fn: function() {
                            if(this.driver === 'restful') this.getStore().reload();
                            this.fireEvent('failureGrid', 'create');
                        }
                    }
                }
            }).show();
    },
});

core.RestfulGrid.register(
    'rh.pvf.shiftmanager.Restful',
    'rh.pvf.shiftmanager.Grid'
);

